import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

maxpool3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

inline int64_t pooling_output_shape(
    int64_t input_size,
    int64_t kernel_size,
    int64_t padding,
    int64_t stride,
    int64_t dilation,
    bool ceil_mode
) {
    int64_t output_size;
    if (ceil_mode) {
        output_size = (input_size + 2 * padding - dilation * (kernel_size - 1) - 1 + stride - 1) / stride + 1;
    } else {
        output_size = (input_size + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    }
    if (padding > 0) {
        if ((output_size - 1) * stride >= input_size + padding) {
            --output_size;
        }
    }
    return std::max<int64_t>(output_size, 0);
}

__global__ void maxpool3d_kernel(
    const float* input,
    float* output,
    int batch_size,
    int channels,
    int input_D,
    int input_H,
    int input_W,
    int output_D,
    int output_H,
    int output_W,
    int kernel_size,
    int stride,
    int padding,
    int dilation
) {
    int64_t index = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t total_elements = batch_size * channels * output_D * output_H * output_W;

    if (index >= total_elements) return;

    int64_t idx = index;
    int64_t batch = idx / (channels * output_D * output_H * output_W);
    idx %= (channels * output_D * output_H * output_W);
    int64_t channel = idx / (output_D * output_H * output_W);
    idx %= (output_D * output_H * output_W);
    int64_t out_d = idx / (output_H * output_W);
    idx %= (output_H * output_W);
    int64_t out_h = idx / output_W;
    int64_t out_w = idx % output_W;

    int start_d = out_d * stride - padding;
    int start_h = out_h * stride - padding;
    int start_w = out_w * stride - padding;

    float max_val = -INFINITY;

    for (int i = 0; i < kernel_size; ++i) {
        int curr_d = start_d + i * dilation;
        if (curr_d < 0 || curr_d >= input_D) continue;

        for (int j = 0; j < kernel_size; ++j) {
            int curr_h = start_h + j * dilation;
            if (curr_h < 0 || curr_h >= input_H) continue;

            for (int k = 0; k < kernel_size; ++k) {
                int curr_w = start_w + k * dilation;
                if (curr_w < 0 || curr_w >= input_W) continue;

                int64_t input_index = batch * channels * input_D * input_H * input_W
                                    + channel * input_D * input_H * input_W
                                    + curr_d * input_H * input_W
                                    + curr_h * input_W
                                    + curr_w;

                float val = __ldg(input + input_index);
                max_val = fmaxf(max_val, val);
            }
        }
    }

    int64_t output_index = batch * channels * output_D * output_H * output_W
                         + channel * output_D * output_H * output_W
                         + out_d * output_H * output_W
                         + out_h * output_W
                         + out_w;

    output[output_index] = max_val;
}

torch::Tensor maxpool3d_cuda(torch::Tensor x, int kernel_size, int stride, int padding, int dilation, bool ceil_mode) {
    TORCH_CHECK(x.dim() == 5, "Input tensor must be 5D (N, C, D, H, W)");
    TORCH_CHECK(x.is_contiguous(), "Input tensor must be contiguous");

    int64_t batch_size = x.size(0);
    int64_t channels = x.size(1);
    int64_t input_D = x.size(2);
    int64_t input_H = x.size(3);
    int64_t input_W = x.size(4);

    auto output_D = pooling_output_shape(input_D, kernel_size, padding, stride, dilation, ceil_mode);
    auto output_H = pooling_output_shape(input_H, kernel_size, padding, stride, dilation, ceil_mode);
    auto output_W = pooling_output_shape(input_W, kernel_size, padding, stride, dilation, ceil_mode);

    auto output = torch::empty({batch_size, channels, output_D, output_H, output_W}, x.options());

    int64_t total_elements = output.numel();
    if (total_elements == 0) return output;

    const int block_size = 256;
    const int grid_size = (total_elements + block_size - 1) / block_size;

    maxpool3d_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        input_D,
        input_H,
        input_W,
        output_D,
        output_H,
        output_W,
        kernel_size,
        stride,
        padding,
        dilation
    );

    return output;
}
"""

maxpool3d_cpp = "torch::Tensor maxpool3d_cuda(torch::Tensor x, int kernel_size, int stride, int padding, int dilation, bool ceil_mode);"

maxpool3d = load_inline(
    name='maxpool3d',
    cpp_sources=maxpool3d_cpp,
    cuda_sources=maxpool3d_source,
    functions=['maxpool3d_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0, dilation: int = 1, return_indices: bool = False, ceil_mode: bool = False):
        super().__init__()
        if return_indices:
            raise ValueError("return_indices not supported in custom implementation")
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding
        self.dilation = dilation
        self.ceil_mode = ceil_mode

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return maxpool3d.maxpool3d_cuda(x, self.kernel_size, self.stride, self.padding, self.dilation, self.ceil_mode)
